CREATE TABLE ship_security_tranq_episode(tranq_episode_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,security_compartment_id bigint NOT NULL REFERENCES ship_security_compartment(security_compartment_id),encounter_id bigint NOT NULL REFERENCES enc_personal_combat(encounter_id),began_combat_round integer NOT NULL CHECK(began_combat_round>0),episode_status text NOT NULL DEFAULT 'active' CHECK(episode_status IN('active','gas-cleared')),concurrency_version bigint NOT NULL DEFAULT 1 CHECK(concurrency_version>0),opened_at timestamptz NOT NULL DEFAULT clock_timestamp(),cleared_at timestamptz,CHECK((episode_status='active')=(cleared_at IS NULL)));
CREATE UNIQUE INDEX ship_one_active_tranq_episode ON ship_security_tranq_episode(security_compartment_id) WHERE episode_status='active';
CREATE TABLE ship_security_tranq_exposure(tranq_exposure_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tranq_episode_id bigint NOT NULL REFERENCES ship_security_tranq_episode(tranq_episode_id),actor_id bigint NOT NULL REFERENCES actor_actor(actor_id),checks_completed integer NOT NULL DEFAULT 0 CHECK(checks_completed>=0),exposure_status text NOT NULL DEFAULT 'active' CHECK(exposure_status IN('active','unconscious','gas-cleared')),concurrency_version bigint NOT NULL DEFAULT 1 CHECK(concurrency_version>0),UNIQUE(tranq_episode_id,actor_id));
CREATE TABLE ship_security_tranq_check_receipt(tranq_check_receipt_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,tranq_exposure_id bigint NOT NULL REFERENCES ship_security_tranq_exposure(tranq_exposure_id),check_sequence integer NOT NULL CHECK(check_sequence>0),combat_round integer NOT NULL CHECK(combat_round>0),task_command_id bigint NOT NULL UNIQUE REFERENCES cmd_actor_task_receipt(command_id),previous_check_dm smallint NOT NULL,task_succeeded boolean NOT NULL,became_unconscious boolean NOT NULL,exposure_version_before bigint NOT NULL,exposure_version_after bigint NOT NULL CHECK(exposure_version_after=exposure_version_before+1),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tranq_exposure_id,check_sequence),CHECK(became_unconscious=NOT task_succeeded));
CREATE TABLE ship_security_tranq_unconscious_state(actor_id bigint PRIMARY KEY REFERENCES actor_actor(actor_id),tranq_exposure_id bigint NOT NULL UNIQUE REFERENCES ship_security_tranq_exposure(tranq_exposure_id),tranq_check_receipt_id bigint NOT NULL UNIQUE REFERENCES ship_security_tranq_check_receipt(tranq_check_receipt_id) DEFERRABLE INITIALLY DEFERRED,unconscious boolean NOT NULL CHECK(unconscious),concurrency_version bigint NOT NULL DEFAULT 1 CHECK(concurrency_version>0),started_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE FUNCTION ship_finalize_tranq_check() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE exposure ship_security_tranq_exposure%ROWTYPE;episode ship_security_tranq_episode%ROWTYPE;compartment ship_security_compartment%ROWTYPE;task cmd_actor_task_receipt%ROWTYPE;actor_campaign bigint;BEGIN SELECT * INTO STRICT exposure FROM ship_security_tranq_exposure WHERE tranq_exposure_id=NEW.tranq_exposure_id FOR UPDATE;SELECT * INTO STRICT episode FROM ship_security_tranq_episode WHERE tranq_episode_id=exposure.tranq_episode_id;SELECT * INTO STRICT compartment FROM ship_security_compartment WHERE security_compartment_id=episode.security_compartment_id;SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id;SELECT campaign_id INTO STRICT actor_campaign FROM actor_actor WHERE actor_id=exposure.actor_id;
 IF episode.episode_status<>'active' OR exposure.exposure_status<>'active' OR actor_campaign<>compartment.campaign_id OR NEW.check_sequence<>exposure.checks_completed+1 OR NEW.combat_round<>(SELECT current_round FROM enc_personal_combat WHERE encounter_id=episode.encounter_id) OR NEW.previous_check_dm<>-(NEW.check_sequence-1) OR task.actor_id<>exposure.actor_id OR task.characteristic_rule_id<>(SELECT rule_id FROM rule_rule WHERE rule_code='characteristic.endurance') OR task.skill_rule_id IS NOT NULL OR task.difficulty_rule_id<>(SELECT rule_id FROM rule_rule WHERE rule_code='difficulty.average') OR task.circumstance_modifier<>NEW.previous_check_dm OR NEW.task_succeeded<>task.succeeded OR NEW.exposure_version_before<>exposure.concurrency_version THEN RAISE EXCEPTION 'Tranq gas requires each-round Endurance checks with cumulative DM-1 and exact task result' USING ERRCODE='23514';END IF;
 UPDATE ship_security_tranq_exposure SET checks_completed=NEW.check_sequence,exposure_status=CASE WHEN NEW.became_unconscious THEN 'unconscious' ELSE 'active' END,concurrency_version=NEW.exposure_version_after WHERE tranq_exposure_id=exposure.tranq_exposure_id;IF NEW.became_unconscious THEN INSERT INTO ship_security_tranq_unconscious_state(actor_id,tranq_exposure_id,tranq_check_receipt_id,unconscious) VALUES(exposure.actor_id,exposure.tranq_exposure_id,NEW.tranq_check_receipt_id,true);END IF;RETURN NEW;END $$;
CREATE TRIGGER ship_tranq_check_final BEFORE INSERT ON ship_security_tranq_check_receipt FOR EACH ROW EXECUTE FUNCTION ship_finalize_tranq_check();
CREATE TABLE ship_security_tranq_clear_receipt(tranq_clear_receipt_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tranq_episode_id bigint NOT NULL UNIQUE REFERENCES ship_security_tranq_episode(tranq_episode_id),episode_version_before bigint NOT NULL,episode_version_after bigint NOT NULL CHECK(episode_version_after=episode_version_before+1),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE FUNCTION ship_finalize_tranq_clear() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE episode ship_security_tranq_episode%ROWTYPE;BEGIN SELECT * INTO STRICT episode FROM ship_security_tranq_episode WHERE tranq_episode_id=NEW.tranq_episode_id FOR UPDATE;IF episode.episode_status<>'active' OR NEW.episode_version_before<>episode.concurrency_version THEN RAISE EXCEPTION 'Tranq gas clearing must match active episode version' USING ERRCODE='23514';END IF;UPDATE ship_security_tranq_episode SET episode_status='gas-cleared',concurrency_version=NEW.episode_version_after,cleared_at=NEW.recorded_at WHERE tranq_episode_id=episode.tranq_episode_id;UPDATE ship_security_tranq_exposure SET exposure_status='gas-cleared',concurrency_version=concurrency_version+1 WHERE tranq_episode_id=episode.tranq_episode_id AND exposure_status='active';RETURN NEW;END $$;CREATE TRIGGER ship_tranq_clear_final BEFORE INSERT ON ship_security_tranq_clear_receipt FOR EACH ROW EXECUTE FUNCTION ship_finalize_tranq_clear();
CREATE FUNCTION ship_reject_tranq_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Ship tranq gas checks and clearing receipts are immutable';END $$;CREATE TRIGGER ship_tranq_check_immutable BEFORE UPDATE OR DELETE ON ship_security_tranq_check_receipt FOR EACH ROW EXECUTE FUNCTION ship_reject_tranq_history_mutation();CREATE TRIGGER ship_tranq_clear_immutable BEFORE UPDATE OR DELETE ON ship_security_tranq_clear_receipt FOR EACH ROW EXECUTE FUNCTION ship_reject_tranq_history_mutation();
CREATE FUNCTION ship_guard_tranq_state() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF pg_trigger_depth()<2 THEN RAISE EXCEPTION 'Ship tranq gas state changes require immutable receipts' USING ERRCODE='23514';END IF;RETURN NEW;END $$;CREATE TRIGGER ship_tranq_episode_guard BEFORE UPDATE OR DELETE ON ship_security_tranq_episode FOR EACH ROW EXECUTE FUNCTION ship_guard_tranq_state();CREATE TRIGGER ship_tranq_exposure_guard BEFORE UPDATE OR DELETE ON ship_security_tranq_exposure FOR EACH ROW EXECUTE FUNCTION ship_guard_tranq_state();CREATE TRIGGER ship_tranq_unconscious_guard BEFORE UPDATE OR DELETE ON ship_security_tranq_unconscious_state FOR EACH ROW EXECUTE FUNCTION ship_guard_tranq_state();
